def full_simplify(expr):
    expr = together(expr)
    expr = cancel(expr)
    expr = factor(expr)
    expr = powdenest(expr, force=True)
    expr = factor_terms(expr)
    return expr

def simplify_bardeen(expr):
    x = symbols('x', positive=True)

    # 1. sustituir sqrt(r**2 + r_0**2) → x
    expr = expr.subs(sqrt(r**2 + r_0**2), x)

    # 2. separar num/den, expandir y eliminar r_0 usando r_0**2 = x**2 - r**2
    #    Esto colapsa el enorme polinomio a uno en (r, x, m) sin r_0
    num, den = expr.as_numer_denom()
    num = num.expand().subs(r_0**2, x**2 - r**2).expand()
    den = den.expand().subs(r_0**2, x**2 - r**2).expand()

    # 3. cancelar factores comunes en espacio (r, x, m)
    expr = cancel(num / den)
    expr = factor(expr)

    # 4. revertir x → sqrt(r**2 + r_0**2) para resultado en variables originales
    expr = expr.subs(x, sqrt(r**2 + r_0**2))
    expr = factor(expr)

    return expr

def simplify_dymnikova(expr):
    x = symbols('x', positive=True)
    z = symbols('z', positive=True)

    # 1. sustituir exp(r**3/r_s**3) → x, simplificar racional
    expr = expr.subs(exp(r**3/r_s**3), x)
    expr = cancel(expr)
    expr = factor(expr)

    # 2. pasar a exponenciales negativos: x → 1/z, z = exp(-r³/r_s³)
    #    distribuye el e^(-2u) dentro del bracket
    expr = expr.subs(x, 1/z)
    expr = cancel(expr)

    # 3. colectar por potencias de r_s y factorizar cada coeficiente
    #    revela 4r_s¹²(1-z)², -8r³r_s⁹·z(1-z), etc.
    num, den = expr.as_numer_denom()
    num = collect(num.expand(), r_s, func=factor)
    expr = num / den

    # 4. revertir z → exp(-r³/r_s³)
    expr = expr.subs(z, exp(-r**3/r_s**3))

    return expr
